{"kind": "content", "icon": "🛎️", "head": "सेवाएँ क्या हैं?", "points": ["अमूर्त: छू नहीं सकते", "अविभाज्यता", "असंगति", "स्वामित्व हस्तांतरण नहीं", "तुरंत उपभोग"], "say": "सेवा वह आर्थिक गतिविधि है जो हमारी किसी ज़रूरत को पूरा करती है, पर जिसे छुआ नहीं जा सकता, जैसे डॉक्टर का इलाज या बैंक की सुविधा। सेवाएँ अमूर्त होती हैं, यानी उन्हें रखा नहीं जा सकता। उनका उत्पादन और उपभोग साथ साथ होता है। एक ही सेवा अलग अलग समय पर अलग गुणवत्ता की हो सकती है। सेवा में स्वामित्व नहीं मिलता, सिर्फ़ उपयोग मिलता है।", "ext": 1},
{"kind": "content", "icon": "🏦", "head": "बैंक – पैसे का घर", "points": ["बचत, चालू, आवर्ती, सावधि खाते", "ऋण और अग्रिम", "चेक, ड्राफ्ट, ऑनलाइन भुगतान", "लॉकर सुविधा", "बैंक का राष्ट्रीयकरण 1969"], "say": "बैंक लोगों से पैसा जमा करते हैं और ज़रूरतमंदों को कर्ज़ देते हैं। खाते कई तरह के होते हैं, बचत खाता, चालू खाता, आवर्ती जमा खाता और सावधि जमा। बैंक चेक, ड्राफ्ट और ऑनलाइन भुगतान की सुविधा देते हैं, लॉकर में कीमती सामान रखने की जगह भी। उन्नीस सौ उनहत्तर में बड़े बैंकों के राष्ट्रीयकरण से बैंक की सुविधा गाँवों तक पहुँचने लगी।", "ext": 1},
{"kind": "content", "icon": "💳", "head": "आधुनिक बैंकिंग", "points": ["ATM, डेबिट-क्रेडिट कार्ड", "इंटरनेट बैंकिंग, मोबाइल बैंकिंग", "UPI: तुरंत भुगतान", "जन धन योजना", "साइबर धोखाधड़ी से सावधानी"], "say": "आज बैंकिंग बहुत आसान हो गई है। ए टी एम से कभी भी पैसे निकाले जा सकते हैं। डेबिट और क्रेडिट कार्ड से दुकान पर भुगतान होता है। इंटरनेट और मोबाइल बैंकिंग से घर बैठे लेन देन हो जाता है। यू पी आई से तुरंत पैसे भेजे जा सकते हैं। जन धन योजना से करोड़ों गरीबों के खाते खुले। पर ओ टी पी और पिन किसी को नहीं बताना चाहिए।", "ext": 1},
{"kind": "content", "icon": "🛡️", "head": "बीमा – जोखिम से सुरक्षा", "points": ["जीवन बीमा", "स्वास्थ्य बीमा", "संपत्ति बीमा, वाहन बीमा", "फ़सल बीमा", "अधिक लोगों से कम जोखिम का बँटवारा"], "say": "बीमा जोखिम से सुरक्षा का साधन है। इसमें हम थोड़ा थोड़ा पैसा प्रीमियम के रूप में देते हैं और किसी नुकसान की स्थिति में कंपनी हमें भरपाई करती है। जीवन बीमा परिवार को सुरक्षा देता है। स्वास्थ्य बीमा इलाज का खर्च उठाता है। वाहन और संपत्ति का बीमा भी होता है। किसानों के लिए फ़सल बीमा योजना भी है। बहुत से लोगों का प्रीमियम मिलकर कुछ लोगों के नुकसान की भरपाई करता है।", "ext": 1},
{"kind": "content", "icon": "🚆", "head": "परिवहन के साधन", "points": ["सड़क, रेल, जल, वायु", "माल और यात्री दोनों", "रेल: सबसे बड़ा जाल", "जल परिवहन सबसे सस्ता", "हवाई मार्ग सबसे तेज़"], "say": "परिवहन व्यापार की जान है, क्योंकि वह माल को उत्पादक से उपभोक्ता तक पहुँचाता है। सड़क परिवहन छोटी दूरी और घर घर पहुँच के लिए अच्छा है। रेल परिवहन सस्ता और भारी माल के लिए सबसे उपयुक्त है। जल परिवहन विदेशी व्यापार के लिए सबसे सस्ता है। हवाई परिवहन सबसे तेज़ है और खराब होने वाले सामान और बहुत ज़रूरी चीज़ों के लिए ठीक रहता है।", "ext": 1},
{"kind": "content", "icon": "📮", "head": "संचार सेवाएँ", "points": ["डाक सेवा: स्पीड पोस्ट, पार्सल", "दूरसंचार: मोबाइल, इंटरनेट", "ईमेल, वीडियो कॉल", "संचार से व्यापार तेज़", "ग्रामीण संचार"], "say": "संचार सेवाएँ व्यापार में सूचना तुरंत पहुँचाती हैं। डाक सेवा से चिट्ठियाँ, पार्सल और स्पीड पोस्ट भेजी जाती हैं। दूरसंचार में मोबाइल, इंटरनेट और वीडियो कॉल आते हैं। ईमेल और ऑनलाइन बैठकों से सौदे घंटों की जगह मिनटों में होने लगे हैं। आज गाँवों में भी मोबाइल और इंटरनेट पहुँच गया है, जिससे किसान सीधे बाज़ार भाव जान पाते हैं।", "ext": 1},
{"kind": "content", "icon": "🏚️", "head": "भंडारण या गोदाम", "points": ["माल को सुरक्षित रखना", "माँग और आपूर्ति का संतुलन", "फ़सल कटाई के बाद रखना", "कोल्ड स्टोरेज", "केंद्रीय भंडारण निगम"], "say": "माल बनता कभी और बिकता कभी और है। इस अंतर को भरने के लिए भंडारण की ज़रूरत पड़ती है। गोदाम में माल सुरक्षित रखा जाता है और ज़रूरत पर बाज़ार में लाया जाता है। फलों और सब्ज़ियों के लिए कोल्ड स्टोरेज चाहिए। केंद्रीय भंडारण निगम और राज्य भंडारण निगम किसानों और व्यापारियों को गोदाम की सुविधा देते हैं।", "ext": 1},
{"kind": "content", "icon": "📣", "head": "विज्ञापन और अन्य सेवाएँ", "points": ["विज्ञापन से ग्राहक तक पहुँच", "पैकेजिंग और ब्रांडिंग", "शिक्षा, स्वास्थ्य और पर्यटन", "सेवा क्षेत्र का GDP में बड़ा हिस्सा", "लाखों को रोज़गार"], "say": "विज्ञापन ग्राहकों तक जानकारी पहुँचाने का साधन है। पैकेजिंग और ब्रांडिंग उत्पाद को पहचान देती है। शिक्षा, स्वास्थ्य और पर्यटन भी सेवाएँ हैं। आज भारत की अर्थव्यवस्था में सेवा क्षेत्र का हिस्सा सबसे बड़ा है और यह लाखों लोगों को रोज़गार देता है। इसलिए सेवाओं की गुणवत्ता सुधारना बहुत ज़रूरी है।", "ext": 1},
